//! Pass 1 of `minime.pass1` on one window, one frame at a time: median, registration
//! image, shift (given or estimated), tophat, running max projection, block maxima over
//! the seed blocks, frame quality, and the corrected frames buffered tile by tile for the
//! tile store (`minime.tiles`: one file per 64 x 64 tile, each `(n, th, tw)` uint8).

use crate::motion::{registration_from_denoised, Motion, MotionParams, Reg};
use crate::npy;
use crate::preprocess::{median_blur, shift, tophat};
use serde::Deserialize;

/// `ref_pass1.py`'s `params.json`: the motion parameters plus tile size, seed window and
/// the window `[t0, t1)`.
#[derive(Debug, Clone, Deserialize)]
pub struct Pass1Params {
    #[serde(flatten)]
    pub motion: MotionParams,
    pub tile: usize,
    pub seeds_wnd: usize,
    pub seeds_stp: usize,
    pub t0: usize,
    pub t1: usize,
}

/// One tile of `tiles.tile_grid`: rows `y0..y1`, columns `x0..x1`.
#[derive(Debug, Clone, Copy)]
pub struct Tile {
    pub y0: usize,
    pub y1: usize,
    pub x0: usize,
    pub x1: usize,
}

impl Tile {
    pub fn pixels(&self) -> usize {
        (self.y1 - self.y0) * (self.x1 - self.x0)
    }
}

/// `tiles.tile_grid`: row-major tiles of `tile` pixels, the last row and column cut short.
pub fn tile_grid(h: usize, w: usize, tile: usize) -> Vec<Tile> {
    (0..h)
        .step_by(tile)
        .flat_map(|y0| {
            (0..w).step_by(tile).map(move |x0| Tile {
                y0,
                y1: h.min(y0 + tile),
                x0,
                x1: w.min(x0 + tile),
            })
        })
        .collect()
}

/// `pass1.seed_block_edges`: sorted unique starts/stops of Minian's rolling seed windows
/// (`ceil(t / stp) + 1` centres from `np.linspace(0, t - 1)`, half width `ceil(wnd / 2)`),
/// plus 0 and `t`.
pub fn seed_block_edges(t: usize, wnd: usize, stp: usize) -> Vec<usize> {
    let mut edges = vec![0, t];
    for (a, b) in crate::seeds::rolling_windows(t, wnd, stp) {
        edges.push(a);
        edges.push(b);
    }
    edges.sort_unstable();
    edges.dedup();
    edges
}

/// `pass1.Pass1` for one worker that starts at the window's first frame.
pub struct Pass1 {
    p: MotionParams,
    pub grid: Vec<Tile>,
    pub edges: Vec<usize>,
    motion: Option<Motion>,
    pub max_proj: Vec<u8>,
    pub block_max: Vec<u8>, // (edges.len() - 1, h, w)
    pub shifts: Vec<f32>,   // (t, 2) dy, dx
    /// The estimated shifts before the cast to float32 (`motion.estimate`'s float64), (t, 2);
    /// empty when every shift was given.
    pub shifts64: Vec<f64>,
    pub quality: Vec<f32>, // empty without a template
    pub t: usize,
    block: usize,
    tiles: Vec<Vec<u8>>, // corrected frames since the last `take_tiles`, per tile
    buffered: usize,
}

impl Pass1 {
    /// `t`: the window's frame count (block edges span it). `motion`: the template, for
    /// estimating shifts and for frame quality; without it every `push` needs a shift.
    pub fn new(p: &Pass1Params, motion: Option<Motion>) -> Self {
        let (h, w, t) = (p.motion.h, p.motion.w, p.t1 - p.t0);
        let edges = seed_block_edges(t, p.seeds_wnd, p.seeds_stp);
        let grid = tile_grid(h, w, p.tile);
        Self {
            p: p.motion.clone(),
            tiles: vec![Vec::new(); grid.len()],
            grid,
            block_max: vec![0; (edges.len() - 1) * h * w],
            edges,
            motion,
            max_proj: vec![0; h * w],
            shifts: Vec::new(),
            shifts64: Vec::new(),
            quality: Vec::new(),
            t: 0,
            block: 0,
            buffered: 0,
        }
    }

    pub fn n_blocks(&self) -> usize {
        self.edges.len() - 1
    }

    /// Begin at frame `a` of the window instead of its first: a chunk worker's `Pass1` (its
    /// `shifts`, `shifts64` and `quality` then start at frame `a`, its block maxima span the
    /// window and `merge_chunk` folds them into the window's).
    pub fn start_at(&mut self, a: usize) {
        self.t = a;
    }

    /// Fold in a chunk run on another `Pass1` of this window (see `start_at`): frames `a..a+n`,
    /// its max projection, block maxima (the same layout as ours) and per-frame shifts and
    /// quality. Maxima are exact in any order; the per-frame vectors are placed at their frames.
    #[allow(clippy::too_many_arguments)]
    pub fn merge_chunk(
        &mut self,
        a: usize,
        n: usize,
        max_proj: &[u8],
        block_max: &[u8],
        shifts: &[f32],
        shifts64: &[f64],
        quality: &[f32],
    ) -> Result<(), String> {
        if max_proj.len() != self.max_proj.len() || block_max.len() != self.block_max.len() {
            return Err(format!(
                "chunk maxima hold {} + {} values, expected {} + {}",
                max_proj.len(),
                block_max.len(),
                self.max_proj.len(),
                self.block_max.len()
            ));
        }
        if shifts.len() != 2 * n
            || !(shifts64.is_empty() || shifts64.len() == 2 * n)
            || !(quality.is_empty() || quality.len() == n)
        {
            return Err(format!(
                "chunk of {n} frames holds {} shifts and {} qualities",
                shifts.len() / 2,
                quality.len()
            ));
        }
        if a + n > *self.edges.last().unwrap() {
            return Err(format!(
                "chunk {a}..{} is past the window's {} frames",
                a + n,
                self.edges.last().unwrap()
            ));
        }
        for (m, &v) in self.max_proj.iter_mut().zip(max_proj) {
            *m = (*m).max(v);
        }
        for (m, &v) in self.block_max.iter_mut().zip(block_max) {
            *m = (*m).max(v);
        }
        fn put<T: Copy + Default>(dst: &mut Vec<T>, at: usize, src: &[T]) {
            if dst.len() < at + src.len() {
                dst.resize(at + src.len(), T::default());
            }
            dst[at..at + src.len()].copy_from_slice(src);
        }
        put(&mut self.shifts, 2 * a, shifts);
        if !shifts64.is_empty() {
            put(&mut self.shifts64, 2 * a, shifts64);
        }
        if !quality.is_empty() {
            put(&mut self.quality, a, quality);
        }
        self.t = self.t.max(a + n);
        Ok(())
    }

    /// Correct one raw frame (`h * w` uint8) and fold it in. `shift`: `(dy, dx)`, or
    /// `None` to estimate it against the template. Returns the shift used.
    pub fn push(&mut self, raw: &[u8], given: Option<[f32; 2]>) -> Result<[f32; 2], String> {
        let p = &self.p;
        let (h, w) = (p.h, p.w);
        if self.t >= *self.edges.last().unwrap() {
            return Err(format!(
                "more than the window's {} frames",
                self.edges.last().unwrap()
            ));
        }
        let den = median_blur(raw, h, w, p.median_ksize);
        let reg =
            (self.motion.is_some() || !p.motion_before_tophat).then(|| registration_from_denoised(&den, p));
        let [dy, dx] = match (given, &self.motion, &reg) {
            (Some(s), _, _) => s,
            (None, Some(m), Some(r)) => {
                let e = m.estimate(r);
                self.shifts64.extend(e);
                e.map(|v| v as f32)
            }
            _ => return Err("no shift given and no template to estimate it".into()),
        };
        let (blk, warped) = if p.motion_before_tophat {
            let blk = tophat(&shift(&den, h, w, dy, dx), h, w, p.tophat_wnd);
            (blk, reg.map(|r| r.shifted(h, w, dy, dx)))
        } else {
            let Some(Reg::U8(top)) = reg else { unreachable!() };
            let blk = shift(&top, h, w, dy, dx);
            let warped = Reg::U8(blk.clone());
            (blk, Some(warped))
        };
        if let (Some(m), Some(r)) = (&self.motion, &warped) {
            self.quality.push(m.quality(r));
        }
        self.fold(&blk);
        self.shifts.extend([dy, dx]);
        Ok([dy, dx])
    }

    /// Max projection, block maximum and tile buffers of one corrected frame.
    fn fold(&mut self, blk: &[u8]) {
        let w = self.p.w;
        let px = blk.len();
        while self.edges[self.block + 1] <= self.t {
            self.block += 1;
        }
        let bm = &mut self.block_max[self.block * px..(self.block + 1) * px];
        for ((m, b), &v) in self.max_proj.iter_mut().zip(bm.iter_mut()).zip(blk) {
            *m = (*m).max(v);
            *b = (*b).max(v);
        }
        for (tile, buf) in self.grid.iter().zip(&mut self.tiles) {
            for y in tile.y0..tile.y1 {
                buf.extend_from_slice(&blk[y * w + tile.x0..y * w + tile.x1]);
            }
        }
        self.t += 1;
        self.buffered += 1;
    }

    /// Frames buffered since the last `take_tiles`.
    pub fn buffered(&self) -> usize {
        self.buffered
    }

    /// The buffered frames, one `(n, th, tw)` uint8 buffer per tile (append each to its
    /// tile file), and an empty buffer.
    pub fn take_tiles(&mut self) -> Vec<Vec<u8>> {
        self.buffered = 0;
        self.tiles.iter_mut().map(std::mem::take).collect()
    }
}

/// The pass's results as `.npy` files named like `ref_pass1.py`'s `ref/` (plus
/// `summary.json`); `tile_crc`: CRC-32 of every tile file as written.
pub fn outputs(p1: &Pass1, tile_crc: &[u32], summary: serde_json::Value) -> Vec<(String, Vec<u8>)> {
    let (h, w, n) = (p1.p.h, p1.p.w, p1.t);
    let edges: Vec<i64> = p1.edges.iter().map(|&v| v as i64).collect();
    let mut out = vec![
        ("max_proj.npy".to_string(), npy::write(&[h, w], &p1.max_proj)),
        (
            "block_max.npy".into(),
            npy::write(&[p1.n_blocks(), h, w], &p1.block_max),
        ),
        ("block_edges.npy".into(), npy::write(&[edges.len()], &edges)),
        ("shifts.npy".into(), npy::write(&[n, 2], &p1.shifts)),
        ("tile_crc.npy".into(), npy::write(&[tile_crc.len()], tile_crc)),
    ];
    if !p1.shifts64.is_empty() {
        out.push(("shifts64.npy".into(), npy::write(&[n, 2], &p1.shifts64)));
    }
    if !p1.quality.is_empty() {
        out.push(("quality.npy".into(), npy::write(&[n], &p1.quality)));
    }
    out.push((
        "summary.json".into(),
        serde_json::to_vec_pretty(&summary).unwrap(),
    ));
    out
}

/// CRC-32 (IEEE, as `zlib.crc32`) of `bytes`, continuing from `crc`.
pub fn crc32(bytes: &[u8], crc: u32) -> u32 {
    static TABLE: std::sync::OnceLock<[u32; 256]> = std::sync::OnceLock::new();
    let table = TABLE.get_or_init(|| {
        let mut t = [0u32; 256];
        for (i, v) in t.iter_mut().enumerate() {
            let mut c = i as u32;
            for _ in 0..8 {
                c = if c & 1 != 0 {
                    0xEDB8_8320 ^ (c >> 1)
                } else {
                    c >> 1
                };
            }
            *v = c;
        }
        t
    });
    let mut c = !crc;
    for &b in bytes {
        c = table[((c ^ u32::from(b)) & 0xFF) as usize] ^ (c >> 8);
    }
    !c
}

